class LogSettings {
  private static level = 1;              // static side: one slot

  get current(): number { return LogSettings.level; }
  set current(v: number) { LogSettings.level = v; }
}

const a = new LogSettings();
const b: LogSettings = new LogSettings();
a.current = 3;
console.log(b.current);                  // 3
